// RGBA Uint8ClampedArray
export function buffBar305Px(){
  const raw=zlib.brotliDecompressSync(Buffer.from(BLOB,'base64')), px=new Uint8ClampedArray(600*120*4);
  for(let i=0,j=0;i<600*120;i++,j+=3){ px[i*4]=raw[j]; px[i*4+1]=raw[j+1]; px[i*4+2]=raw[j+2]; px[i*4+3]=255; }
  return px;
}
